import { create } from 'zustand'
import { ExpoSpeechRecognitionModule } from 'expo-speech-recognition'

interface SpeechPermissionStore {
	hasSpeechPermission: boolean | null
	setHasSpeechPermission: (hasSpeechPermission: boolean) => void
	init: () => Promise<void>
}

export const useSpeechPermissionStore = create<SpeechPermissionStore>(
	(set) => ({
		hasSpeechPermission: null,
		setHasSpeechPermission: (hasSpeechPermission: boolean) => {
			set({ hasSpeechPermission })
		},
		init: async () => {
			const permission = await ExpoSpeechRecognitionModule.getPermissionsAsync()
			set({
				hasSpeechPermission:
					permission.status === 'granted' ||
					permission.status === 'undetermined'
			})
		}
	})
)
